"""Generates docs/data_dictionary.md from schema.py (Step 1)."""
from __future__ import annotations

from pathlib import Path

from .schema import TABLES


def write_data_dictionary(path: Path) -> Path:
    L = ["# Data dictionary\n",
         "_Generated by `python -m ssp docs` from `src/ssp/schema.py` - the same definitions drive the loader, "
         "the validator and the SQL DDL, so this document cannot drift from the code._\n",
         "Conventions: quantities are in the SKU's `base_uom` unless stated; money in USD; dates ISO `YYYY-MM-DD`; "
         "weeks are ISO weeks `2026W01`..`2026W52` (week 1 starts Monday 2025-12-29, the planning as-of date). "
         "`Req` = required (non-empty). `Unique` = unique across the table.\n"]
    for layer, title in (("input", "Input (source) tables"), ("derived", "Derived (planner output) tables"),
                         ("ground_truth", "Ground truth (kept separate)")):
        L.append(f"\n## {title}\n")
        for t in [t for t in TABLES.values() if t.layer == layer]:
            L.append(f"\n### `{t.name}`\n\n{t.description}\n")
            L.append(f"- **Primary key:** `{', '.join(t.pk)}`")
            if t.fks:
                L.append("- **Foreign keys:** " + "; ".join(f"`{c}` -> `{r}.{rc}`" for c, r, rc in t.fks))
            if t.unique_together:
                L.append("- **Unique together:** " + "; ".join("(" + ", ".join(u) + ")" for u in t.unique_together))
            if t.cardinality:
                L.append("- **Cardinality:** " + "; ".join(t.cardinality))
            if t.lifecycle:
                L.append(f"- **Lifecycle:** {t.lifecycle}")
            L += ["", "| field | type | req | allowed values | unit | unique | validation rule |", "|---|---|---|---|---|---|---|"]
            for f in t.fields:
                allowed = ", ".join(v for v in f.allowed if v) if f.allowed else ""
                rule = f.rule
                if f.pattern:
                    rule = (rule + "; " if rule else "") + f"format `{f.pattern}`"
                if f.min is not None or f.max is not None:
                    rule = (rule + "; " if rule else "") + f"range [{'' if f.min is None else f.min}, {'' if f.max is None else f.max}]"
                L.append(f"| `{f.name}` | {f.type} | {'yes' if f.required else 'no'} | {allowed} | {f.unit} | "
                         f"{'yes' if f.unique else ''} | {rule.replace('|', '/')} |")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(L) + "\n", newline="\n")
    return path
